// ***************
// Filename: uart_top.sv
// Author: FPGA Cores 4 U
// Description: uart with its AXI4-Lite register interface, the block designs
//   and testbenches instantiate: the register map uart_regs (u_regs,
//   src/include/uart_regs.sv, ID "UART", VERSION and DATE at 0x00-0x08, the
//   registers from 0x10) and the logic uart (u_core, src/uart.sv), joined by
//   the register interface uart_regs_if (u_regs_if). Generated by
//   ip/scripts/regmap_gen.py from uart_regs.json and the ports of uart:
//   regenerate after changing either. Clock - aclk. Reset - synchronous
//   active low aresetn.
// Date: 2026-10-20
module uart_top #(
  parameter int CLK_HZ = 100_000_000,
  parameter int BAUD = 115_200,
  parameter int FIFO_DEPTH = 512
) (
  input  logic aclk,
  input  logic aresetn,
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  axil_if.slave s_axil,
  // s_axis: axis_if.slave (ip/shared/src/interfaces/axis_if.sv), DATA_W = 8
  axis_if.slave s_axis,
  // m_axis: axis_if.master (ip/shared/src/interfaces/axis_if.sv), DATA_W = 8
  axis_if.master m_axis,
  // uart: uart_if.dte (ip/shared/src/interfaces/uart_if.sv) {uart_txd_o=txd uart_rxd_i=rxd}
  uart_if.dte uart
);
  localparam logic [63:0] FCW64 = ((64'(BAUD) * 64'd16 << 32) + (64'(CLK_HZ) >> 1)) / 64'(CLK_HZ);
  // register interface between the register map and the logic
  uart_regs_if u_regs_if ();

  uart_regs #(
    .FCW_RST(FCW64[31:0])
  ) u_regs (
    .aclk,
    .aresetn,
    .s_axil(s_axil),
    .r(u_regs_if)
  );
  uart #(
    .CLK_HZ(CLK_HZ),
    .BAUD(BAUD),
    .FIFO_DEPTH(FIFO_DEPTH)
  ) u_core (
    .aclk,
    .aresetn,
    .s_axis,
    .m_axis,
    .pins(uart),
    .regs(u_regs_if)
  );
endmodule
